{
 "scene": {
  "engine": "unity",
  "unitsPerMeter": 1,
  "listener": "first_person",
  "player": "player",
  "objects": [
   {
    "id": "player",
    "role": "player",
    "label": "You",
    "motion": "moves",
    "notes": "The person wearing the headset; the listener is their head."
   },
   {
    "id": "lucy",
    "role": "character",
    "label": "Lucy",
    "material": "winter coat",
    "motion": "moves",
    "notes": "Junior detective, the player's guide; walks around, kneels at clues."
   },
   {
    "id": "dexter",
    "role": "character",
    "label": "Dexter",
    "material": "winter coat",
    "motion": "moves",
    "notes": "Holds a mug of hot cocoa."
   },
   {
    "id": "sherman",
    "role": "character",
    "label": "Sherman",
    "material": "winter coat",
    "motion": "moves"
   },
   {
    "id": "serena",
    "role": "character",
    "label": "Serena",
    "material": "winter coat",
    "motion": "moves"
   },
   {
    "id": "tony",
    "role": "character",
    "label": "Tony",
    "material": "winter coat",
    "motion": "moves",
    "notes": "The culprit; in the finale he runs fast across the snow and dodges, gets dazed when hit."
   },
   {
    "id": "tony_sled",
    "label": "Tony's sled",
    "radiusM": 0.4,
    "material": "red plastic",
    "motion": "moves",
    "notes": "Planted in the snow near Tony."
   },
   {
    "id": "frosty",
    "label": "Frosty",
    "radiusM": 0.6,
    "material": "snow",
    "motion": "moves",
    "notes": "Fallen snowman lying in the snow mid-room; placed at runtime, then still."
   },
   {
    "id": "polaroid_camera",
    "label": "Polaroid camera",
    "material": "plastic",
    "motion": "moves",
    "notes": "Held in the player's left hand; appears when they pinch."
   }
  ],
  "environment": {
   "setting": "Mixed-reality detective game: the player's real room becomes a snowy backyard with five kids around a knocked-over snowman",
   "time": "overcast winter afternoon",
   "weather": "light steady snowfall, gentle gusty wind",
   "ground": "snow, soft and fresh, a few cm deep",
   "enclosure": "open air in fiction; snowy redwoods hide the walls; play area 3 to 6 m across",
   "notes": "Meta Quest mixed reality. Virtual snow covers the floor, light snowfall drifts down, snowy redwoods, shrubs, rocks and drifts stand around the edges of the room. Five kids in winter coats (Lucy the junior detective, Dexter with a mug of cocoa, Sherman, Serena, Tony the troublemaker with a sled) stand around a knocked-over snowman called Frosty. The player photographs clues with a Polaroid camera and can throw snowballs. Kids' dialogue is the game's own recorded voice lines, already positioned on each kid's head by the game code: do not compose speech. A music score plays quietly. Satie's sounds replace the game's simple synthesized footsteps, scoops, throws, snowball hits and camera sounds."
  },
  "events": [
   {
    "name": "step",
    "description": "The player's own footstep in the snow.",
    "surfaces": [
     "snow"
    ],
    "by": "player"
   },
   {
    "name": "kid_step",
    "description": "A kid's footstep in the snow while walking or running; fired at that kid.",
    "surfaces": [
     "snow"
    ]
   },
   {
    "name": "scoop",
    "description": "The player scoops snow from the floor with their hand to make a snowball.",
    "surfaces": [
     "snow"
    ],
    "by": "player"
   },
   {
    "name": "kid_scoop",
    "description": "A kid crouches and scoops a snowball from the snow at their feet.",
    "surfaces": [
     "snow"
    ]
   },
   {
    "name": "throw",
    "description": "A snowball leaves a hand (player or kid): a short whoosh at the thrower."
   },
   {
    "name": "snowball_hit",
    "description": "A snowball bursts on something: a kid, Frosty, a tree, the ground. Soft powdery splat."
   },
   {
    "name": "snowball_hit_player",
    "description": "A kid's snowball bursts on the player's face or chest.",
    "by": "player"
   },
   {
    "name": "punch_hit",
    "description": "The player bops a kid with their hand: a soft padded thump on a puffy coat."
   },
   {
    "name": "shutter",
    "description": "The Polaroid's shutter fires with a flash.",
    "with": "polaroid_camera",
    "by": "player"
   },
   {
    "name": "print_eject",
    "description": "The instant print motors out of the camera's slot (about 0.9 s).",
    "with": "polaroid_camera"
   },
   {
    "name": "photo_drop",
    "description": "A Polaroid print flutters down onto the snow."
   },
   {
    "name": "kid_stunned",
    "description": "A kid is stunned (seeing stars) after a hit."
   }
  ],
  "states": [
   {
    "name": "menu",
    "description": "Title screen and menus before play; the world is quiet."
   },
   {
    "name": "investigating",
    "description": "Normal calm play: talking to kids, photographing clues."
   },
   {
    "name": "snowball_fight",
    "description": "An 18 second snowball fight: all kids pelting the player and each other."
   },
   {
    "name": "chase",
    "description": "The finale: Tony flees and dodges, tension up."
   },
   {
    "name": "case_closed",
    "description": "Case solved: the ending collage; relieved and warm."
   }
  ]
 }
}
